def design(p):
 # A toggle is a physical state mechanism, not a decorated pill.
 toggles=[
 ('cantilever-toggle','支点をもつ長いレバーが、二つの停止位置へしなやかに傾く。','<span class="cl-base"><i class="cl-pin"></i><span class="cl-lever"><b></b></span><em class="cl-light"></em></span>', '''${width:156px;height:92px}.sop-cantilever-toggle .cl-base{position:absolute;inset:14px 0;background:linear-gradient(135deg,#48464a,#211f23);border:1px solid #85828b;border-radius:40% 8% 8% 40%;box-shadow:inset 0 2px 1px #fff2,0 12px 20px #0005}.sop-cantilever-toggle .cl-pin{position:absolute;width:32px;height:32px;left:19px;top:14px;border-radius:50%;background:radial-gradient(circle,#293239 25%,#8a9da5 28%,#46545d 67%,#161a1d 70%)}.sop-cantilever-toggle .cl-lever{position:absolute;left:32px;top:26px;width:94px;height:12px;background:linear-gradient(#d2d8dc,#68737d);transform-origin:4px 50%;transform:rotate(calc(19deg - var(--p)*38deg));border-radius:7px;box-shadow:0 6px 7px #0005}.sop-cantilever-toggle .cl-lever b{position:absolute;right:-1px;top:-11px;width:27px;height:34px;border-radius:7px;background:linear-gradient(95deg,#527681,#9dbcc4,#37565f)}.sop-cantilever-toggle .cl-light{position:absolute;right:10px;top:27px;width:5px;height:5px;background:#506052;border-radius:50%;box-shadow:0 0 calc(var(--p)*12px) #a1e0a7;opacity:calc(.35 + var(--p)*.65)}'''),
 ('shoji-toggle','木の桟をもつ障子が滑り、奥の灯りを開く。','<span class="sj-frame"><span class="sj-glow"></span><span class="sj-leaf"><i></i><i></i><i></i><i></i><i></i><i></i></span><b class="sj-grip"></b></span>', '''${width:144px;height:82px}.sop-shoji-toggle .sj-frame{position:absolute;inset:7px;border:5px solid #6c5240;background:radial-gradient(at 75% 30%,#f2d799,#a17e53);border-radius:3px;box-shadow:0 5px 14px #0005,inset 0 0 12px #0007;overflow:hidden}.sop-shoji-toggle .sj-leaf{position:absolute;inset:1px 50% 1px 1px;background:#d9d6c6;display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(2,1fr);gap:3px;border:3px solid #84694e;transform:translateX(calc(var(--p)*58px));box-shadow:3px 0 4px #0005}.sop-shoji-toggle .sj-leaf i{background:radial-gradient(#efede3,#c5c5b9);border:1px solid #a39983}.sop-shoji-toggle .sj-grip{position:absolute;left:48px;top:26px;width:4px;height:11px;border-radius:2px;background:#493b30;transform:translateX(calc(var(--p)*58px))}'''),
 ('pneumatic-toggle','透明な空気室の中で、弾性膜が凹凸を反転する。','<span class="pn-housing"><i class="pn-membrane"></i><b class="pn-core"></b><em class="pn-meter"></em></span>', '''${width:118px;height:100px}.sop-pneumatic-toggle .pn-housing{position:absolute;inset:3px 12px;border-radius:50%;background:radial-gradient(at 28% 15%,#e3ece650,#657e7a22 43%,#18302b);border:1px solid #acc9bc;box-shadow:inset 0 3px 2px #fff5,0 12px 18px #0004}.sop-pneumatic-toggle .pn-membrane{position:absolute;inset:15px;border-radius:50%;background:radial-gradient(at 50% calc(18% + var(--p)*50%),#c4ede5,#476b65 54%,#193f38 90%);box-shadow:inset 0 calc(7px - var(--p)*12px) 13px #0006,0 calc(var(--p)*5px) 7px #0004;transform:scale(calc(.85 + var(--p)*.12))}.sop-pneumatic-toggle .pn-core{position:absolute;width:5px;height:5px;left:43px;top:39px;background:#d1ebdf;border-radius:50%}.sop-pneumatic-toggle .pn-meter{position:absolute;left:28px;right:28px;bottom:10px;height:2px;background:linear-gradient(90deg,#7bcaae calc(var(--p)*100%),#304e48 0)}'''),
 ('braided-toggle','二本の革紐が編み目を変えて、留め具を反対側へ運ぶ。','<span class="br-bed"><i class="br-strand one"></i><i class="br-strand two"></i><span class="br-clasp"></span></span>', '''${width:152px;height:67px}.sop-braided-toggle .br-bed{position:absolute;inset:10px 0;border-radius:6px;background:#242024;border:1px solid #746264;box-shadow:inset 0 3px 10px #0007}.sop-braided-toggle .br-strand{position:absolute;left:8px;right:8px;top:17px;height:6px;border-radius:9px;background:repeating-linear-gradient(70deg,#b9a282 0 3px,#80684c 3px 5px);transform:rotate(calc(-8deg + var(--p)*16deg));transform-origin:center}.sop-braided-toggle .br-strand.two{transform:rotate(calc(8deg - var(--p)*16deg));background:repeating-linear-gradient(110deg,#79565a 0 3px,#4b3039 3px 5px)}.sop-braided-toggle .br-clasp{position:absolute;left:15px;top:7px;width:30px;height:29px;border:3px solid #c7bfa8;background:linear-gradient(#798482,#3a4140);border-radius:3px;box-shadow:0 3px 5px #0008;transform:translateX(calc(var(--p)*90px))}''')]
 for id,desc,art,css in toggles:p('toggles',id,desc,css,markup='<button type="button" class="sop-toggle sop-$" role="switch" aria-checked="true" aria-label="'+desc.split('。')[0]+'"><span class="switch-art" aria-hidden="true">'+art+'</span></button>')
 for id,desc,css in [
 ('scalloped-folio','波打つ紙端と縦の綴じ穴が、読み物を一枚の台紙に収める。','${--sop-ink:#3e3433;--sop-accent-ink:#92665e;background:#e8dbc9;border-radius:2px 22px 22px 2px;border-left:14px solid #584044;box-shadow:5px 8px 0 #312a30,0 14px 25px #0004}$:before{content:"";position:absolute;top:10px;bottom:10px;left:5px;width:8px;background:radial-gradient(circle,#211c21 2px,transparent 3px) 0 0/8px 25px}$ .sop-surface-content{padding-left:34px}$:hover{box-shadow:7px 10px 0 #312a30,0 16px 30px #0005;transition:box-shadow .4s}'),
 ('kiln-surface','焼き物の厚い口縁と釉薬の溜まりが、内容を囲む浅い器になる。','${--sop-ink:#f1e8da;--sop-accent-ink:#cdbfa1;background:radial-gradient(ellipse at 30% 10%,#89806e,#3c514e 65%);border:6px solid #747567;border-radius:45px 13px 38px 17px;box-shadow:inset 0 0 0 2px #c8b99966,inset 0 8px 15px #142c2655,0 9px 17px #0005}$ .sop-surface-content{padding:32px}$:hover{border-color:#a99b81;transition:border-color .7s}'),
 ('plotted-surface','横の余白から伸びる括弧が、情報の位置を正確に示す。','${--sop-ink:#d7e5ec;--sop-accent-ink:#81bace;background:#142a35;border:0;border-left:2px solid #91bcc8;overflow:visible}$:before,$:after{content:"";position:absolute;width:22px;height:16px;border:1px solid #91bcc8;left:-8px;pointer-events:none}$:before{top:0;border-right:0;border-bottom:0}$:after{bottom:0;border-right:0;border-top:0}$ .sop-surface-content{padding:28px 22px 28px 36px}$:hover:before{width:35px;transition:width .5s}'),
 ('inlaid-surface','寄木の細い帯が角を折れ、中心の内容と分離して縁を走る。','${--sop-ink:#e7dfd0;--sop-accent-ink:#ccaf88;background:#282326;border:1px solid #76614d;border-radius:3px;padding:7px}$ .sop-surface-content{border:1px solid #675a46;background:linear-gradient(135deg,#4e383077,#282326 55%);padding:27px}$:before{content:"";position:absolute;inset:3px;background:repeating-linear-gradient(115deg,#a17a49 0 5px,#362826 5px 9px,#ceae73 9px 10px);z-index:-1}$:hover .sop-surface-content{background-position:10px 0;transition:background-position .7s}'),
 ('vellum-pocket','半透明の封筒の口が上辺に重なり、内容を安全に見せる。','${--sop-ink:#384752;--sop-accent-ink:#496f80;background:#cad9dd;border-radius:5px 5px 28px 28px;box-shadow:0 1px 0 #fff9,inset 0 -8px 18px #89a2ab55;overflow:hidden}$:before{content:"";position:absolute;left:0;right:0;top:0;height:42px;background:linear-gradient(120deg,#f1f5f0aa,#87a5b166);clip-path:polygon(0 0,100% 0,50% 100%);border-top:2px solid #f3f8f3}$ .sop-surface-content{padding-top:55px}'),
 ('caption-surface','狭いキャプション帯と広い本文を分けた、資料用のカード。','${--sop-ink:#dce3de;--sop-accent-ink:#b1ccc0;background:#222b2a;border:1px solid #556763;border-radius:0;padding-top:6px;border-top:18px solid #435b51}$ .sop-surface-content{padding:24px 20px}$:focus-within{border-color:#a7c5b6}'),
 ]:p('blocks',id,desc,css,kind='B' if id=='caption-surface' else 'A')
 for id,desc,css in [
 ('book-spine-accordion','冊子の背に並ぶ丸い番号から、章の内容を開く。','${--acc-bg:#e7d5b8;--acc-ink:#433a35;--acc-accent:#774943;--acc-muted:#707563;--acc-line:#8b6d5644;--acc-radius:0;border-left:12px solid #74534a;padding-left:6px}$ .sop-accordion-item{margin:0;border:0;border-bottom:1px solid #977b65}$ .sop-accordion-index{border:1px solid #987a5e;border-radius:50%;width:30px;height:30px;display:grid;place-items:center}$ .sop-accordion-sign{border-radius:50%;background:#a6876755;padding:12px}$ .sop-accordion-item[data-open=true]{background:#f1e1c8;box-shadow:inset 3px 0 #985849}'),
 ('suspension-accordion','細い吊り線で支えた見出しが、開いた本文と静かに離れる。','${--acc-bg:#202a34;--acc-accent:#a8c5d6;--acc-radius:4px;padding-left:17px;border-left:1px solid #768da366}$ .sop-accordion-item{overflow:visible;border:0;margin-bottom:18px;box-shadow:0 7px 15px #0003}$ .sop-accordion-item:before{content:"";position:absolute;width:18px;height:1px;background:#889eae;left:-18px;top:32px}$ .sop-accordion-index{font-size:18px;font-weight:200}$ .sop-accordion-badge{display:none}$ .sop-accordion-item[data-open=true]{border-bottom:2px solid #9fc0d2}'),
 ('concertina-accordion','斜めの折り目をもつ厚い紙が、章ごとに奥行きを変える。','${--acc-bg:#d6d0bb;--acc-ink:#363f3c;--acc-accent:#54675c;--acc-muted:#707563;--acc-radius:2px}$ .sop-accordion-item{margin-bottom:0;border:0;border-bottom:1px solid #7a8773;box-shadow:inset -10px 0 #b3b7a0;clip-path:polygon(0 0,100% 4%,100% 100%,0 96%)}$ .sop-accordion-item:nth-child(even){box-shadow:inset 10px 0 #bec3ab}$ .sop-accordion-trigger{padding-right:29px}$ .sop-accordion-item[data-open=true]{background:#e4e1d2;clip-path:polygon(0 0,100% 0,100% 100%,0 100%)}'),
 ('notched-accordion','片側の切欠きが、選んだ段の見出しと内容を一枚に結ぶ。','${--acc-bg:#273439;--acc-accent:#d0bdaa;--acc-radius:0}$ .sop-accordion-item{border:0;border-right:5px solid #766653;clip-path:polygon(0 0,calc(100% - 10px) 0,100% 10px,100% 100%,0 100%);margin-bottom:10px}$ .sop-accordion-index{font:24px Georgia;color:#b39773;min-width:26px}$ .sop-accordion-badge{display:none}$ .sop-accordion-item[data-open=true]{border-right-color:#e0c9aa;background:#31444b}'),
 ]:p('accordions',id,desc,css)
 for id,desc,css in [
 ('carbon-ribbon-field','暗いリボンの中央に文字を置き、左右の端で入力の活性を示す。','${--field-bg:#182024;--field-ink:#e4e7db;--field-accent:#bfd485;--field-radius:0}$ .sop-field-shell{border:0;border-top:1px solid #91a263;border-bottom:1px solid #91a263;border-left:10px solid #6c7948;border-right:10px solid #6c7948;transform:skewX(-3deg);background:linear-gradient(90deg,#b4c97022,transparent 12%,transparent 88%,#b4c97022)}$ input{transform:skewX(3deg)}$ .sop-field-shell:focus-within{border-left-color:#d0e39d;border-right-color:#d0e39d;box-shadow:0 3px 0 #73874755}'),
 ('punched-field','角のパンチ穴と印字の余白をもつ、チケット状の入力欄。','${--field-bg:#eee1c6;--field-ink:#4a4036;--field-accent:#9a6a48;--field-muted:#7c725a;--field-radius:0;color-scheme:light;background:#eee1c6;padding:15px;border:1px solid #ac9878}$ .sop-field-shell{border:1px solid #a28763;border-left:8px dotted #423b32;background:#eee1c6;box-shadow:4px 4px 0 #ad916d44}$ .sop-field-shell:focus-within{box-shadow:5px 5px 0 #a67d5344;border-bottom-width:3px}$ .sop-field-label{letter-spacing:2px;font-family:Consolas}'),
 ('banked-field','入力面の左端をせり上げ、文字を横長の浅い溝に載せる。','${--field-bg:#313745;--field-ink:#edf0e8;--field-accent:#b8b8d3;--field-radius:3px}$ .sop-field-shell{border:0;border-bottom:1px solid #adb0d1;border-left:13px solid #6b6b89;box-shadow:inset 0 5px 9px #15172288,0 1px 0 #8583a266;background:#292d39;transition:border-left-width .35s,box-shadow .35s}$ .sop-field-shell:focus-within{border-left-width:5px;box-shadow:inset 0 2px 5px #12162488,0 3px 0 #8583a266}'),
 ('ruled-caption-field','ラベルを罫線上に置き、入力と補足を整然と二段に分ける。','${--field-bg:#1f292a;--field-ink:#e6eddf;--field-accent:#c1d0ae;--field-radius:0}$ .sop-field-label{padding-bottom:7px;border-bottom:1px solid #576d62}$ .sop-field-shell{margin-top:0;border:0;background:none;border-bottom:2px solid #718773;box-shadow:none}$ .sop-field-shell:focus-within{border-color:#d0e0bb;background:#3d594022}$ .sop-field-hint{padding-top:6px}'),
 ]:p('textboxes',id,desc,css,kind='B' if id=='ruled-caption-field' else 'A')
 for id,desc,css in [
 ('bellows-button','折り畳んだ金属の側面が、押下に合わせて縮む。','${--sop-action-ink:#f4edd9;--sop-action-accent:#c9b78f;background:#534a45;border:1px solid #a6957e;border-radius:3px;padding:16px 27px;box-shadow:0 5px 0 #362c29,0 7px 0 #78645a,0 11px 0 #292223;transform:translateY(-4px);transition:transform .35s,box-shadow .35s}$ .sop-action-art{display:none}$:hover{transform:translateY(-2px);box-shadow:0 4px 0 #362c29,0 6px 0 #78645a,0 8px 0 #292223}$:active{transform:translateY(3px);box-shadow:0 1px 0 #362c29}'),
 ('porcelain-key-button','小さな磁器のキーが、文字を囲む縁と押し込みの影を持つ。','${--sop-action-ink:#475355;--sop-action-accent:#68978e;background:linear-gradient(140deg,#f6f4eb,#becdcb);border:1px solid #d8ece4;border-radius:9px 9px 23px 23px;padding:16px 29px;box-shadow:inset 0 2px #fff8,0 7px 0 #738d89,0 12px 14px #0004;transition:transform .4s,box-shadow .4s}$ .sop-action-art{display:none}$ .sop-action-icon{border-left:1px solid #728a7c66;padding-left:8px;width:26px}$:active{transform:translateY(5px);box-shadow:inset 0 2px #fff8,0 2px 0 #738d89,0 5px 6px #0004}'),
 ('suture-button','細い縫い目で包んだ布の面が、触れると柔らかく張る。','${--sop-action-ink:#eaded2;--sop-action-accent:#caad9d;background:repeating-linear-gradient(0deg,#5d3d4c 0 1px,#533444 1px 3px);border:1px solid #a28593;border-radius:30% 12% 30% 12%;padding:17px 32px;box-shadow:inset 0 0 0 4px #533444,0 6px 14px #0004;outline:1px dashed #c6a5b4;outline-offset:-6px;transition:border-radius .6s,transform .6s}$ .sop-action-art{display:none}$:hover{border-radius:18px;transform:translateY(-2px)}'),
 ('arrowhead-button','広いラベル面と矢尻形の先端が、実行の向きを明確にする。','${--sop-action-ink:#edf3de;--sop-action-accent:#d4e7ae;background:#32473d;border:0;border-left:4px solid #a3bf85;border-radius:0;padding:17px 30px 17px 21px;clip-path:polygon(0 0,calc(100% - 17px) 0,100% 50%,calc(100% - 17px) 100%,0 100%)}$ .sop-action-art{display:none}$ .sop-action-icon{transition:transform .45s}$:hover .sop-action-icon{transform:translateX(6px)}$[aria-busy=true]{background:#475d4d}'),
 ('spinneret-button','小さな糸巻きの軸がラベルの脇で回り、押下の手応えを伝える。','${--sop-action-ink:#e6e2ed;--sop-action-accent:#b1a5da;background:#292733;border:1px solid #706784;border-radius:4px;padding:14px 20px;gap:22px}$ .sop-action-art{inset:7px auto 7px 8px;width:14px;border:2px solid #a8a0b6;border-radius:50%;opacity:.6;background:repeating-linear-gradient(0deg,transparent 0 3px,#a69bbf 3px 4px);transform:rotate(-10deg);transition:transform .6s}$ .sop-action-label{padding-left:15px}$:hover .sop-action-art{transform:rotate(10deg)}'),
 ('shortcut-button','実行ラベルと小さなキーキャップを一つの操作としてまとめる。','${--sop-action-ink:#e4e8e5;--sop-action-accent:#b4c9b9;background:#25312d;border:1px solid #52685c;border-radius:8px;padding:12px 15px;gap:18px}$ .sop-action-art{display:none}$ .sop-action-icon{width:25px;height:25px;border:1px solid #718675;border-bottom-width:3px;border-radius:4px;padding:4px;background:#1c2823}$:hover{background:#34473b}'),
 ]:p('buttons',id,desc,css,kind='B' if id=='shortcut-button' else 'A')
